def process():return '<div class="process">'+''.join(f'<div class="process-step"><span>0{i}</span><h3>{t}</h3><p>{b}</p></div>' for i,t,b in [(1,'Tell us what you need.','Bring your artwork, your goal, or the thing you’ve been trying to explain. We’ll help you work out the details.'),(2,'Review the quote.','We’ll talk through the material, design, quantity, timing, and budget—then give you a clear quote.'),(3,'Approve the proof.','Review your design proof, approve the details, and we’ll move your project into production or launch.')])+'</div>'
