def contact_page():
 options=['General project','Business signs','Vinyl banners','Vehicle graphics & lettering','Custom T-shirt printing','NCR forms & service work orders','RD Graphics','Alley Cats Screen Printing','Copy Write Printing','Relevant Design','Rocket Sites','Rocket','Rocket Pro','Get Found Now','Events & Promotion']
 return crumbs('Start a project')+hero('Let’s make<br><span class="accent">it happen.</span>','Start a conversation','Tell us what you’re working on. We’ll help you find the right next step—whether it’s a few business cards or a whole new brand.',None)+'<section class="section white-section" style="padding-top:55px"><div class="container contact-layout"><div><div class="contact-card"><div class="contact-row"><span>Give us a call</span><a href="tel:+16017360663">(601) 736-0663</a></div><div class="contact-row"><span>Send a text</span><a href="sms:+16014419328">(601) 441-9328</a></div><div class="contact-row"><span>Email McKenzie</span><a href="mailto:discover+intake@relevantdesign.cc" style="font-size:20px">discover+intake@relevantdesign.cc</a></div><div class="contact-row"><span>Come see us</span><address>907 Main Street<br>Columbia, Mississippi 39429</address>'+textlink('Get directions','https://www.google.com/maps/search/?api=1&query=Relevant+Design+907+Main+Street+Columbia+MS+39429')+'</div></div>'+mckenzie_card()+shop_callout()+'<p class="small-note" style="margin-top:20px">Looking for Alley Cats or Copy Write? You’re in the right place. Start here for any of our companies and brands.</p></div><form id="quote-form" name="relevant-contact" method="POST" action="/contact/thanks/" data-netlify="true" netlify-honeypot="bot-field" class="contact-form"><input type="hidden" name="form-name" value="relevant-contact"><p hidden aria-hidden="true"><label>Leave this blank<input name="bot-field" tabindex="-1" autocomplete="off"></label></p><h2>A little about your project.</h2><p>Tell McKenzie what you have in mind. Submit the details here and our team will review your request.</p><div class="form-grid"><label>Your name<input name="name" autocomplete="name" required maxlength="100" placeholder="First and last name"></label><label>Business / organization<input name="company" autocomplete="organization" maxlength="120" placeholder="Who’s this for?"></label><label>Email<input name="email" type="email" autocomplete="email" required maxlength="200" placeholder="you@yourbusiness.com"></label><label>Phone (optional)<input name="phone" type="tel" autocomplete="tel" maxlength="40" placeholder="Best number to reach you"></label><label>What can we help with?<select name="service">'+''.join(f'<option>{s}</option>' for s in options)+'</select></label><label>When do you need it?<input name="deadline" maxlength="100" placeholder="A date, or “flexible”"></label><label class="full">Tell us about the project<textarea name="details" required maxlength="1800" placeholder="What are you making? Include sizes, quantities, colors, and any other helpful details."></textarea></label></div><button class="button" type="submit">Send project request '+AR+'</button><p class="form-note">This form sends your request securely to our intake team. We’ll follow up about artwork and the next steps. Do not include passwords or payment details. <a href="/privacy/">Privacy details</a></p><p id="quote-status" class="form-status" role="status" aria-live="polite"></p><noscript><p>JavaScript is disabled. Email your project details directly to <a href="mailto:discover+intake@relevantdesign.cc">discover+intake@relevantdesign.cc</a>, or call (601) 736-0663.</p></noscript></form></div></section>'+faq_section(DEFAULT_FAQ[1:4])

def services_page():return crumbs('What we do')+hero('Signs. Shirts. Print.<br><span class="accent">Design & websites.</span>','Design · Print · Signs · Websites','Find the service you need below. For projects that include signs, apparel, printing, and a website, start with one conversation at our Columbia shop.',None)+'<section class="section white-section" style="padding-top:50px"><div class="container">'+service_cards()+'</div></section><section class="section"><div class="container two-col"><div>'+eyebrow('For your kind of business')+'<h2>For businesses,<br>schools & churches.</h2></div><div><p>We work with business owners, contractors, retailers, medical practices, churches, schools, authors, nonprofits, and community organizations.</p><p>You don’t need to know the name of a material or which department to ask for. Tell us the job the finished piece needs to do. We’ll help you choose the right approach.</p><div class="use-cases"><span>Launch a business</span><span>Refresh a brand</span><span>Promote an event</span><span>Outfit a team</span><span>Get online</span><span>Reorder essentials</span></div></div></div></section>'+cta()
