def schema(path,title,faqs):
 org={'sameAs':['https://www.facebook.com/relevantdesign1/'],'image':ORIGIN+'/assets/jones-truck.webp','@type':'LocalBusiness','@id':ORIGIN+'/#business','name':'Relevant Design','legalName':'Relevant Design Studios, LLC','url':ORIGIN+'/','logo':ORIGIN+'/assets/relevant.svg','telephone':'+1-601-736-0663','email':'discover+intake@relevantdesign.cc','address':{'@type':'PostalAddress','streetAddress':'907 Main Street','addressLocality':'Columbia','addressRegion':'MS','postalCode':'39429','addressCountry':'US'},'areaServed':[{'@type':'City','name':'Columbia, Mississippi'},{'@type':'State','name':'Mississippi'}],'hasOfferCatalog':{'@type':'OfferCatalog','name':'Design, print, signs and websites','itemListElement':[{'@type':'OfferCatalog','name':a[1],'url':ORIGIN+'/'+a[0]+'/'} for a in SERVICES]}}
 graph=[org,{'@type':'WebSite','@id':ORIGIN+'/#website','name':'Relevant Design','url':ORIGIN+'/'},{'@type':'WebPage','@id':ORIGIN+path+'#page','name':title,'url':ORIGIN+path,'isPartOf':{'@id':ORIGIN+'/#website'},'about':{'@id':ORIGIN+'/#business'}}]
 if path!='/':graph.append({'@type':'BreadcrumbList','itemListElement':[{'@type':'ListItem','position':1,'name':'Home','item':ORIGIN+'/'},{'@type':'ListItem','position':2,'name':title.split('|')[0].strip(),'item':ORIGIN+path}]})
 if faqs:graph.append(faq_schema(faqs))
 if path=='/rocket-sites/':
  for name,price,tag,features in PLANS:graph.append({'@type':'Service','name':name,'provider':{'@id':ORIGIN+'/#business'},'description':tag+' Plus $199 setup.','offers':{'@type':'Offer','url':ORIGIN+path+'#plans','priceCurrency':'USD','price':str(price),'priceSpecification':{'@type':'UnitPriceSpecification','priceCurrency':'USD','price':str(price),'unitText':'month'}}})
 slug=path.strip('/')
 if slug in PRODUCT_DATA:
  d=PRODUCT_DATA[slug]
  graph.append({'@type':'Service','@id':ORIGIN+path+'#service','name':d['kicker'],'description':d['intro'],'url':ORIGIN+path,'provider':{'@id':ORIGIN+'/#business'},'areaServed':{'@type':'State','name':'Mississippi'}})
  graph[2]['mainEntity']={'@id':ORIGIN+path+'#service'}
 if slug in FOCUSED:
  d=FOCUSED[slug]
  graph.append({'@type':'Service','@id':ORIGIN+path+'#service','name':d['name'],'description':d['lead'],'url':ORIGIN+path,'provider':{'@id':ORIGIN+'/#business'},'areaServed':{'@type':'State','name':'Mississippi'}})
  graph[2]['mainEntity']={'@id':ORIGIN+path+'#service'}
 if path=='/work/':
  graph[2]['@type']='CollectionPage'
  graph.append({'@type':'ItemList','name':'Relevant Design portfolio','itemListElement':[{'@type':'ListItem','position':i+1,'item':{'@type':'ImageObject','name':p[1],'caption':p[2],'description':p[5],'contentUrl':ORIGIN+'/assets/'+p[0]+'.webp'}} for i,p in enumerate(PROJECTS)]})
 picture=PAGE_IMAGES.get(path)
 if picture:graph[2]['primaryImageOfPage']={'@type':'ImageObject','contentUrl':ORIGIN+'/assets/'+picture+'.webp','width':IMAGE_META[picture]['width'],'height':IMAGE_META[picture]['height']}
 return {'@context':'https://schema.org','@graph':graph}

