 for old,new in aliases.items():
  dest=OUT/old.strip('/')/'index.html';dest.parent.mkdir(parents=True,exist_ok=True);dest.write_text(f'<!doctype html><html lang="en"><head><meta charset="utf-8"><meta http-equiv="refresh" content="0;url={new}"><link rel="canonical" href="{ORIGIN}{new}"><title>Relevant Design</title></head><body><p>This page has moved. <a href="{new}">Continue to Relevant Design</a>.</p></body></html>')
 (OUT/'contact'/'thanks'/'index.html').parent.mkdir(parents=True,exist_ok=True)
 (OUT/'contact'/'thanks'/'index.html').write_text(document('/contact/thanks/','Thanks for reaching out | Relevant Design','Your project request is on its way to Relevant Design.',crumbs('Thank you')+hero('Thanks for reaching out.','Your request is in','McKenzie and the team will review your details. If you have artwork or a photo to share, you can reply when we contact you.',None)+'<div class="container" style="padding-bottom:90px">'+button('Back to the homepage','/')+'</div>').replace('index,follow,max-image-preview:large','noindex,follow'))
 (OUT/'sitemap.xml').write_text('<?xml version="1.0" encoding="UTF-8"?><urlset xmlns="http://www.sitemaps.org/schemas/sitemap/0.9">'+''.join(f'<url><loc>{ORIGIN}{p}</loc></url>' for p in PAGES)+'</urlset>')
