 (OUT/'robots.txt').write_text('User-agent: *\nAllow: /\nSitemap: '+ORIGIN+'/sitemap.xml\nSitemap: '+ORIGIN+'/image-sitemap.xml\n')
 (OUT/'404.html').write_text(document('/404/','Page not found | Relevant Design','Find your way back to Relevant Design.',hero('Page not found.','Page not found','Let’s get you back to the right place.',None)+'<div class="container" style="padding-bottom:90px">'+button('Back to the homepage','/')+'</div>').replace('index,follow,max-image-preview:large','noindex,follow'))
 (OUT/'llms.txt').write_text('# Relevant Design\n\nDesign, signs, printing and websites in Columbia, Mississippi.\n\nContact: 907 Main Street, Columbia, MS 39429. Phone: +1 601-736-0663. Email: discover+intake@relevantdesign.cc.\n\n'+''.join(f'- [{t.split("|")[0].strip()}]({ORIGIN}{p}): {d}\n' for p,(t,d,_,__) in PAGES.items()))
 (OUT/'_headers').write_text('/assets/*\n  Cache-Control: public, max-age=86400\n/*\n  X-Content-Type-Options: nosniff\n  Referrer-Policy: strict-origin-when-cross-origin\n  Permissions-Policy: camera=(), microphone=(), geolocation=()\n')
 print(f'Built {len(PAGES)} content pages, 4 legacy routes, 404, sitemap, robots and metadata for {ORIGIN}')
